window.MGProseData("bc830b3ab456a69be1df2d037edafd9d48728ac1063b5b3a4e3ee976d9e2d31c",{"html":"\u003ch2>Part 1: Mathematical Appendix — Flow Analysis and Stack Convergence\u003c/h2>\n\u003ch3>1. Energy Potential and Vector Field\u003c/h3>\n\u003cp>The system state is \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">⊤\u003c/mi>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z = (x, y)^\\top \\in \\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, and the energy function is\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>4\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x, y) = \\frac{1}{2}\\left(x^2 + 2y^2\\right) + \\frac{1}{4}(x + y)^4.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>The gradient vector field \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla f(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is given by:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>x\u003c/mi>\u003c/msub>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>y\u003c/mi>\u003c/msub>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>3\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>y\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>3\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla f(z) = \\begin{pmatrix} \\partial_x f(x, y) \\\\ \\partial_y f(x, y) \\end{pmatrix} = \\begin{pmatrix} x + (x + y)^3 \\\\ 2y + (x + y)^3 \\end{pmatrix}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>The Hessian matrix \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla^2 f(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla^2 f(z) = \\begin{pmatrix} 1 + 3(x + y)^2 \u0026amp; 3(x + y)^2 \\\\ 3(x + y)^2 \u0026amp; 2 + 3(x + y)^2 \\end{pmatrix} = \\begin{pmatrix} 1 \u0026amp; 0 \\\\ 0 \u0026amp; 2 \\end{pmatrix} + 3(x + y)^2 \\begin{pmatrix} 1 \u0026amp; 1 \\\\ 1 \u0026amp; 1 \\end{pmatrix}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nFor any non-zero vector \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">⊤\u003c/mi>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v = (v_1, v_2)^\\top \\in \\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmi mathvariant=\"normal\">⊤\u003c/mi>\u003c/msup>\u003cmsup>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>v\u003c/mi>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsubsup>\u003cmi>v\u003c/mi>\u003cmn>2\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≥\u003c/mo>\u003cmsubsup>\u003cmi>v\u003c/mi>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsubsup>\u003cmi>v\u003c/mi>\u003cmn>2\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≥\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>v\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v^\\top \\nabla^2 f(z) v = v_1^2 + 2v_2^2 + 3(x + y)^2(v_1 + v_2)^2 \\ge v_1^2 + 2v_2^2 \\ge \\|v\\|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nHence, \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⪰\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla^2 f(z) \\succeq I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> uniformly for all \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z \\in \\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. This establishes that \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is \u003cstrong>1-strongly convex\u003c/strong> on \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> with respect to the standard Euclidean norm.\u003c/p>\n\u003chr>\n\u003ch3>2. Forward Global Well-Posedness\u003c/h3>\n\u003cp>Consider the Cauchy problem for the autonomous gradient flow:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>z\u003c/mi>\u003cmo>˙\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\dot{z}(t) = -\\nabla f(z(t)), \\quad z(0) = z_0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>Local Well-Posedness:\u003c/strong> The components of \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla f(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> are polynomials, hence \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C^\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and locally Lipschitz continuous on \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. By the Picard–Lindelöf theorem, there exists a unique maximal solution \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z(t) = \\Phi_t(z_0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> defined on an interval \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[0, T_{\\max})\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>.\u003c/li>\n\u003cli>\u003cstrong>Global Existence (\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_{\\max} = +\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>):\u003c/strong> Along any trajectory, the energy evolves according to:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmi>d\u003c/mi>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmover accent=\"true\">\u003cmi>z\u003c/mi>\u003cmo>˙\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{d}{dt} f(z(t)) = \\langle \\nabla f(z(t)), \\dot{z}(t) \\rangle = -\\|\\nabla f(z(t))\\|^2 \\le 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nThus, \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(z(t)) \\le f(z_0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> for all \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t \\in [0, T_{\\max})\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. Moreover, \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is coercive:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsqrt>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msqrt>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x, y) \\ge \\frac{1}{2}(x^2 + 2y^2) \\ge \\frac{1}{2}\\|z\\|^2 \\implies \\|z(t)\\| \\le \\sqrt{2 f(z_0)}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nConsequently, every trajectory remains inside the compact sublevel set \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>:\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsqrt>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msqrt>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal{K} = \\{z \\in \\mathbb{R}^2 : \\|z\\| \\le \\sqrt{2f(z_0)}\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. By the escape of compact sets theorem, no finite-time blowup can occur, meaning \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_{\\max} = +\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. The continuous flow map \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Phi_t: \\mathbb{R}^2 \\to \\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is globally well-defined for all \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and satisfies the continuous semigroup property \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>∘\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Phi_{t+s} = \\Phi_t \\circ \\Phi_s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> with \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Phi_0 = I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>.\u003c/li>\n\u003c/ol>\n\u003chr>\n\u003ch3>3. Identification of the Unique Equilibrium\u003c/h3>\n\u003cp>An equilibrium \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsup>\u003cmi>y\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">⊤\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z^* = (x^*, y^*)^\\top\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> satisfies \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>z\u003c/mi>\u003cmo>˙\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\dot{z} = -\\nabla f(z^*) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>y\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\begin{cases} x + (x + y)^3 = 0, \u0026amp; (1) \\\\ 2y + (x + y)^3 = 0. \u0026amp; (2) \\end{cases}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nSubtracting (2) from (1) yields:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>y\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x - 2y = 0 \\implies x = 2y.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nSubstituting \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x = 2y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> back into (2):\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>y\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>27\u003c/mn>\u003cmsup>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2y + (3y)^3 = y(2 + 27y^2) = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nSince \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>27\u003c/mn>\u003cmsup>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2 + 27y^2 \\ge 2 \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> for all \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">y \\in \\mathbb{R}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, the unique real root is \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">y = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, which immediately gives \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>.\u003c/p>\n\u003cp>Thus, the unique equilibrium is the origin:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">⊤\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z^* = (0, 0)^\\top.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nAt this point, \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(z^*) = f(0, 0) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>.\u003c/p>\n\u003chr>\n\u003ch3>4. Derivation of the Contractivity Bound: \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|\\Phi_t(z) - \\Phi_t(w)\\| \\le e^{-t}\\|z - w\\|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/h3>\n\u003cp>Let \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z(t) = \\Phi_t(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w(t) = \\Phi_t(w)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> be two trajectories initialized at \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z, w \\in \\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. Define the squared Euclidean distance:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D(t) = \\frac{1}{2}\\|z(t) - w(t)\\|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nDifferentiating with respect to \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmi>d\u003c/mi>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmover accent=\"true\">\u003cmi>z\u003c/mi>\u003cmo>˙\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmover accent=\"true\">\u003cmi>w\u003c/mi>\u003cmo>˙\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{d}{dt} D(t) = \\langle z(t) - w(t), \\dot{z}(t) - \\dot{w}(t) \\rangle = -\\langle \\nabla f(z(t)) - \\nabla f(w(t)), z(t) - w(t) \\rangle.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nBy the mean-value theorem for vector-valued functions and the uniform lower bound \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo>⪰\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla^2 f \\succeq I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmo>∫\u003c/mo>\u003cmn>0\u003c/mn>\u003cmn>1\u003c/mn>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">⊤\u003c/mi>\u003c/msup>\u003cmsup>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle \\nabla f(z) - \\nabla f(w), z - w \\rangle = \\int_0^1 (z - w)^\\top \\nabla^2 f(w + s(z - w)) (z - w) \\, ds \\ge \\|z - w\\|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nApplying this 1-strong monotonicity property yields:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmi>d\u003c/mi>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{d}{dt} D(t) \\le -\\|z(t) - w(t)\\|^2 = -2 D(t).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nMultiplying by the integrating factor \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e^{2t}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmi>d\u003c/mi>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{d}{dt}\\left( e^{2t} D(t) \\right) \\le 0 \\implies D(t) \\le e^{-2t} D(0).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nSubstituting \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D(t) = \\frac{1}{2}\\|z(t) - w(t)\\|^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and taking the square root gives:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>t\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|\\Phi_t(z) - \\Phi_t(w)\\| \\le e^{-t}\\|z - w\\|, \\quad \\forall t \\ge 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch3>5. Derivation of the Dissipation Bound: \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(\\Phi_t(z)) \\le e^{-2t}f(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/h3>\n\u003cp>Along any trajectory \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z(t) = \\Phi_t(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, the energy dissipation rate is:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmi>d\u003c/mi>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{d}{dt} f(z(t)) = -\\|\\nabla f(z(t))\\|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nSince \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is 1-strongly convex, for any \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u, v \\in \\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>v\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>u\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(v) \\ge f(u) + \\langle \\nabla f(u), v - u \\rangle + \\frac{1}{2}\\|v - u\\|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nMinimizing the right-hand side over \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v \\in \\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> gives the minimum at \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v = u - \\nabla f(u)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>v\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(v) \\ge f(u) - \\frac{1}{2}\\|\\nabla f(u)\\|^2, \\quad \\forall v \\in \\mathbb{R}^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nEvaluating this inequality at the global minimizer \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v = z^* = (0, 0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> where \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(z^*) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≥\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \\ge f(u) - \\frac{1}{2}\\|\\nabla f(u)\\|^2 \\implies \\|\\nabla f(u)\\|^2 \\ge 2 f(u),\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nwhich is the Polyak–Łojasiewicz (PL) inequality with modulus \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu = 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>.\nApplying this to \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u = z(t)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmi>d\u003c/mi>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{d}{dt} f(z(t)) = -\\|\\nabla f(z(t))\\|^2 \\le -2 f(z(t)).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nIntegrating with the factor \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e^{2t}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmi>d\u003c/mi>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>t\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{d}{dt}\\left( e^{2t} f(z(t)) \\right) \\le 0 \\implies f(\\Phi_t(z)) \\le e^{-2t} f(z), \\quad \\forall t \\ge 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch3>6. Quantitative Convergence for a Stacked Architecture\u003c/h3>\n\u003cp>Each denoising block is \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_\\tau = \\Phi_\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> for a fixed \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\tau \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. Stacking \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> identical blocks produces:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>T\u003c/mi>\u003cmi>τ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmunder>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003cmo>∘\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>∘\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">⏟\u003c/mo>\u003c/munder>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmtext> times\u003c/mtext>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z_n = T_\\tau^n(Z_0) = \\underbrace{(\\Phi_\\tau \\circ \\cdots \\circ \\Phi_\\tau)}_{n \\text{ times}}(Z_0).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nBy the continuous dynamical semigroup property (\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>∘\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Phi_t \\circ \\Phi_s = \\Phi_{t+s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>):\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z_n = \\Phi_{n\\tau}(Z_0).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nBecause the equilibrium \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z^* = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is stationary (\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Phi_t(0) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(0) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>):\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>State-Space Metric Convergence:\u003c/strong> Setting \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> in the contractivity bound:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|Z_n\\| = \\|\\Phi_{n\\tau}(Z_0) - \\Phi_{n\\tau}(0)\\| \\le e^{-n\\tau}\\|Z_0\\|.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>\u003cstrong>Energy Dissipation Convergence:\u003c/strong>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(Z_n) \\le e^{-2n\\tau} f(Z_0).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>\u003cstrong>Perturbation Robustness:\u003c/strong> For any two initial representations \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>W\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z_0, W_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> (e.g., perturbed vs. unperturbed inputs):\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>W\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>W\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|Z_n - W_n\\| \\le e^{-n\\tau}\\|Z_0 - W_0\\|.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003c/ol>\n\u003cp>Both the Euclidean norm and the energy decay geometrically with depth \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> at linear rates \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho = e^{-\\tau} \u0026lt; 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>ρ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho^2 = e^{-2\\tau} \u0026lt; 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> per layer, respectively.\u003c/p>\n\u003chr>\n\u003ch2>Part 2: Proximal Certificate and Firm Nonexpansiveness\u003c/h2>\n\u003ch3>1. Statement of the Proximal Certificate\u003c/h3>\n\u003cp>Let \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r: \\mathbb{R}^d \\to (-\\infty, +\\infty]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> be a proper, lower-semicontinuous (l.s.c.), convex function. Under the convention:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmtext>prox\u003c/mtext>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>arg\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msup>\u003c/mrow>\u003c/munder>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>v\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\text{prox}_r(z) = \\arg\\min_{v \\in \\mathbb{R}^d} \\left\\{ r(v) + \\frac{1}{2}\\|v - z\\|^2 \\right\\},\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nlet \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmtext>prox\u003c/mtext>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p = T(z) = \\text{prox}_r(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. Then for every \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmtext>dom \u003c/mtext>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in \\text{dom } r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r(p) + \\frac{1}{2}\\|p - z\\|^2 + \\frac{1}{2}\\|u - p\\|^2 \\le r(u) + \\frac{1}{2}\\|u - z\\|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch3>2. Proof of the Certificate\u003c/h3>\n\u003cp>The objective function \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ψ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>v\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\psi(v) = r(v) + \\frac{1}{2}\\|v - z\\|^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is 1-strongly convex and proper l.s.c., ensuring that the minimizer \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is unique.\u003c/p>\n\u003cp>By Fermat's rule for convex optimization, \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>ψ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \\in \\partial \\psi(p)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. Because the quadratic term \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{1}{2}\\|\\cdot - z\\|^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is continuously differentiable with gradient \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p - z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, the subdifferential sum rule applies:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \\in \\partial r(p) + (p - z) \\iff z - p \\in \\partial r(p).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nBy definition of the Fenchel subdifferential of \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> at \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, for all \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmtext>dom \u003c/mtext>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in \\text{dom } r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r(u) \\ge r(p) + \\langle z - p, u - p \\rangle. \\qquad (3)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nWe now rewrite the inner product \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle z - p, u - p \\rangle\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> using the Euclidean polarization identity:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u - z\\|^2 = \\|(u - p) + (p - z)\\|^2 = \\|u - p\\|^2 + \\|p - z\\|^2 + 2\\langle u - p, p - z \\rangle.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nRearranging gives:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle z - p, u - p \\rangle = -\\langle p - z, u - p \\rangle = \\frac{1}{2}\\|u - z\\|^2 - \\frac{1}{2}\\|p - z\\|^2 - \\frac{1}{2}\\|u - p\\|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nSubstituting this identity into (3):\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r(u) \\ge r(p) + \\frac{1}{2}\\|u - z\\|^2 - \\frac{1}{2}\\|p - z\\|^2 - \\frac{1}{2}\\|u - p\\|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nRearranging terms yields the desired certificate:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>p\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">■\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r(p) + \\frac{1}{2}\\|p - z\\|^2 + \\frac{1}{2}\\|u - p\\|^2 \\le r(u) + \\frac{1}{2}\\|u - z\\|^2. \\qquad \\blacksquare\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch3>3. Derivation of Firm Nonexpansiveness\u003c/h3>\n\u003cp>Let \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z_1, z_2 \\in \\mathbb{R}^d\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, and define \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmtext>prox\u003c/mtext>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p_1 = T(z_1) = \\text{prox}_r(z_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmtext>prox\u003c/mtext>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p_2 = T(z_2) = \\text{prox}_r(z_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. Since \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmtext>dom \u003c/mtext>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p_1, p_2 \\in \\text{dom } r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\u003c/p>\n\u003col>\n\u003cli>Apply the certificate for \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(z_1, p_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> with test point \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u = p_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r(p_1) + \\frac{1}{2}\\|p_1 - z_1\\|^2 + \\frac{1}{2}\\|p_2 - p_1\\|^2 \\le r(p_2) + \\frac{1}{2}\\|p_2 - z_1\\|^2. \\qquad (4)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>Apply the certificate for \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(z_2, p_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> with test point \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u = p_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>5\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r(p_2) + \\frac{1}{2}\\|p_2 - z_2\\|^2 + \\frac{1}{2}\\|p_1 - p_2\\|^2 \\le r(p_1) + \\frac{1}{2}\\|p_1 - z_2\\|^2. \\qquad (5)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003c/ol>\n\u003cp>Adding inequalities (4) and (5), the potential values \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r(p_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r(p_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> cancel:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>6\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|p_1 - p_2\\|^2 + \\frac{1}{2}\\|p_1 - z_1\\|^2 + \\frac{1}{2}\\|p_2 - z_2\\|^2 \\le \\frac{1}{2}\\|p_2 - z_1\\|^2 + \\frac{1}{2}\\|p_1 - z_2\\|^2. \\qquad (6)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nExpanding the cross-terms on the right-hand side:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|p_2 - z_1\\|^2 = \\|(p_2 - p_1) + (p_1 - z_1)\\|^2 = \\|p_1 - p_2\\|^2 + \\|p_1 - z_1\\|^2 + 2\\langle p_2 - p_1, p_1 - z_1 \\rangle,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|p_1 - z_2\\|^2 = \\|(p_1 - p_2) + (p_2 - z_2)\\|^2 = \\|p_1 - p_2\\|^2 + \\|p_2 - z_2\\|^2 + 2\\langle p_1 - p_2, p_2 - z_2 \\rangle.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nSumming these two expansions and dividing by 2:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{1}{2}\\|p_2 - z_1\\|^2 + \\frac{1}{2}\\|p_1 - z_2\\|^2 = \\|p_1 - p_2\\|^2 + \\frac{1}{2}\\|p_1 - z_1\\|^2 + \\frac{1}{2}\\|p_2 - z_2\\|^2 + \\langle p_1 - p_2, (p_2 - z_2) - (p_1 - z_1) \\rangle.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nSubstituting this expression into the right-hand side of (6) and canceling identical terms on both sides gives:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \\le \\langle p_1 - p_2, (p_2 - z_2) - (p_1 - z_1) \\rangle = \\langle p_1 - p_2, (z_1 - p_1) - (z_2 - p_2) \\rangle.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nRewriting the inner product:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle p_1 - p_2, (z_1 - z_2) - (p_1 - p_2) \\rangle \\ge 0 \\iff \\|p_1 - p_2\\|^2 \\le \\langle p_1 - p_2, z_1 - z_2 \\rangle.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nThis is the characterization of \u003cstrong>firm nonexpansiveness\u003c/strong>.\u003c/p>\n\u003cp>Equivalently, it can be written as:\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|T(z_1) - T(z_2)\\|^2 + \\|(I - T)(z_1) - (I - T)(z_2)\\|^2 \\le \\|z_1 - z_2\\|^2,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nwhich immediately implies nonexpansiveness (Lipschitz continuity with constant 1):\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">■\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|T(z_1) - T(z_2)\\| \\le \\|z_1 - z_2\\|. \\qquad \\blacksquare\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch2>Part 3: Deployment Description (Methods Section Paragraph)\u003c/h2>\n\u003cp>\u003cstrong>Continuous Denoising Dynamics and Multi-Block Stacking.\u003c/strong> Each autonomous denoising block implements the exact continuous-time flow operator \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_\\tau = \\Phi_\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> of the gradient system \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>z\u003c/mi>\u003cmo>˙\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\dot{z} = -\\nabla f(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> over a transit duration \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\tau \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, where the potential \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>y\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>4\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(z) = \\frac{1}{2}(x^2+2y^2) + \\frac{1}{4}(x+y)^4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is uniformly 1-strongly convex. Consequently, each block provides a certified contractive denoising guarantee: for any states \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z, w \\in \\mathbb{R}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>z\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>w\u003c/mi>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|T_\\tau(z) - T_\\tau(w)\\| \\le e^{-\\tau}\\|z - w\\|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, while strictly dissipating the energy via \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(T_\\tau(z)) \\le e^{-2\\tau}f(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. Deploying a depth-\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> cascade \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>T\u003c/mi>\u003cmi>τ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z_n = T_\\tau^n(Z_0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> exploits the continuous semigroup property \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>τ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Phi_\\tau^n = \\Phi_{n\\tau}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, meaning an \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-block stack corresponds exactly to a continuous evolution of total transit time \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t = n\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>. This guarantees exponential convergence toward the unique ground-state equilibrium \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z^* = (0, 0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> with \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|Z_n\\| \\le e^{-n\\tau}\\|Z_0\\|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> and \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>n\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(Z_n) \\le e^{-2n\\tau}f(Z_0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, completely bypassing discretization errors or numerical instabilities.\u003c/p>\n\u003cp>\u003cstrong>Distinction from Proximal Discretization.\u003c/strong> It is mathematically essential to distinguish the flow transit time \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> from the weighting parameter in proximal regularization. In standard proximal formulations \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmtext>prox\u003c/mtext>\u003cmrow>\u003cmi>γ\u003c/mi>\u003cmi>f\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>arg\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>γ\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>z\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\text{prox}_{\\gamma f}(z) = \\arg\\min_u \\{\\gamma f(u) + \\frac{1}{2}\\|u - z\\|^2\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> (which corresponds to an implicit Euler step), \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>γ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\gamma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> acts as a static trade-off coefficient balancing energy minimization against Euclidean displacement, yielding only firm nonexpansiveness (\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmtext>Lip\u003c/mtext>\u003cmo>≤\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\text{Lip} \\le 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>). In our architecture, the coefficient \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{1}{2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> is fixed by definition, and the block is not an implicit Euler step (\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>τ\u003c/mi>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmsub>\u003cmtext>prox\u003c/mtext>\u003cmrow>\u003cmi>τ\u003c/mi>\u003cmi>f\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_\\tau \\ne \\text{prox}_{\\tau f}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>). Instead, \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> represents the continuous physical transit time along the trajectory curve \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>z\u003c/mi>\u003cmo>˙\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\dot{z} = -\\nabla f(z)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>, translating directly into an exponential contractivity modulus \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e^{-\\tau} \u0026lt; 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> that compounds strictly multiplicatively across layers.\u003c/p>\n","source":"assets/content/bc830b3ab456a69be1df2d037edafd9d48728ac1063b5b3a4e3ee976d9e2d31c.html"});
